    """ Add the two signed 31 bits integers a and b
    >>> add_31_bits(7, 13)
    -1
    """
    if a >= 0:
        max_value = 0xffffffff
    else:
        max_value = 0x80000000

    if b >= 0:
        min_value = 0x80000000
    else:
        min_value = 0x7fffffff

