    # initialize stack
    stack = []

    for char in string:
        # if current char is open bracket then push to stack
        if char in '([{':
            stack.append(char)
        # if stack is empty or current char is closing bracket then return False
        elif not stack:
            return False
        else:
            # if top element of stack is not matching then return False
            top_element = stack.pop()
            if char == ')' and top_element != '(':
                return False
            elif char == ']' and top_element != '[':
                return False
            elif char == '}' and top_element != '{':
                return False
    # if stack is not empty then return False
    return not stack


