def count_decimals(number: float) -> int:
    """ Count how many decimals are present after the last integer part

    >>> count_decimals(3.5)
    1
    """
    return int(math.log10(truncate_number(number)))+1

def round_decimals(number: float) -> float:
    """ Round the given number to the closest decimal.

    >>> round_decimals(3.6)
    4
    """
    if truncate_number(number) == number:
        return number
    else:
        decimal_len = count_decimals(number)
        # This condition is to account for case if decimal is bigger than 9
        if decimal_len == 1:
            rounded_number = truncate_number(number)*math.pow(10, decimal_len-1) // math.pow(10, decimal_len-1)
            return float(rounded_number)
        else:
            rounded_number = truncate_number(number)*math.pow(10, decimal_len-1) // math.pow(10, decimal_len-1)
            return round(rounded_number, decimal_len-1)

