def max_depth(paren_string: str) -> int:
    """ Input is a string representing nested parentheses. For each parenthesis pair, return the number of levels of nested parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> max_depth('(()()) ((())) () ((())()())')
    2
    """

    paren_stack = []
    for paren in paren_string:
        if paren == '(':
            paren_stack.append(paren)
        elif paren == ')':
            if len(paren_stack) == 0:
                return -1
            if paren_stack[-1] != '(':
                return -1
            paren_stack.pop()
    if len(paren_stack) == 0:
        return len(paren_string)
    return -1


