def solution(numbers: List[int], target: int) -> int:
    """ Given list of numbers and target, find number of ways to add and multiply
    elements of list to get the target number.
    >>> solution([1, 1, 1, 1, 1], 3)
    5
    """
    if not numbers:
        return 0
    if len(numbers) == 1:
        return 1 if numbers[0] == target else 0
    return solution(numbers[:-1], target - numbers[-1]) + solution(numbers[:-1], target + numbers[-1])

