def dfs(paren: str) -> int:
    """ Input to this function is a string represented nested parentheses separated by spaces.
    This function assumes parentheses only starts and ends with a '(', ']' or ')'. Input is valid.

    Example:
    >>> dfs('(()())')
    2
    >>> dfs('((()))')
    3
    >>> dfs('()')
    1
    >>> dfs('((())()())')
    3
    """
    stack = []
    for c in paren:
        if c in ('(', '['):
            stack.append(c)
        elif c in (')', ']'):
            if len(stack) == 0:
                return -1
            if stack[-1] == '(' and c == ')':
                stack.pop()
            elif stack[-1] == '[' and c == ']':
                stack.pop()
    if len(stack) == 0:
        return len(paren)
    return -1


